<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="feedback"><label>Category<select name="category"><option value="">All categories</option><?php foreach(['prisons'=>'Prisons','client'=>'Client'] as $value=>$label):?><option value="<?=$value?>" <?=$dashboard['category']===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['pending'=>'Awaiting review','approved'=>'Approved'] as $value=>$label):?><option value="<?=$value?>" <?=$dashboard['status']===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><button>Apply filters</button><span class="filter-count"><?=h((string)$dashboard['total'])?> submission(s)</span></form></section>
<?php if(!$dashboard['feedback']):?><section class="panel empty-state"><?=admin_icon('message')?><h2>You’re all caught up.</h2><p>No feedback matches these filters. New ideas and bug reports will appear here.</p></section><?php endif?>
<?php foreach($dashboard['feedback'] as $item):?><article class="panel feedback-note" id="feedback-<?=h((string)$item['id'])?>"><div class="panel-heading"><div class="author"><span class="avatar"><?=h(strtoupper(substr($item['username'],0,1)))?></span><div><h2><?=h($item['username'])?></h2><p>#<?=h((string)$item['id'])?> · <?=h(gmdate('d M Y, H:i',(int)$item['created_at']))?> UTC</p></div></div><span class="badge <?=$item['status']==='approved'?'success':'purple'?>"><?=$item['status']==='approved'?'Approved':'Awaiting review'?></span></div>
<div class="badge-row"><span class="badge muted"><?=h(ucfirst($item['category']))?></span><span class="badge muted"><?=h(ucfirst($item['kind']))?></span><code class="player-id"><?=h($item['uuid'])?></code></div><div class="feedback-message"><?=nl2br(h($item['message']))?></div>
<?php if($item['status']==='pending'):?><form method="post" class="reply-form"><?php admin_csrf()?><input type="hidden" name="action" value="feedback_approve"><input type="hidden" name="feedback_id" value="<?=h((string)$item['id'])?>"><label>Reply to the player <span class="optional">Optional</span><textarea name="reply" maxlength="2000" rows="2" placeholder="Thanks for sharing this. Here’s what we’re thinking…"></textarea></label><div class="form-footer"><p>The player receives your approval and reply on their next game login.</p><button class="primary"><?=admin_icon('check')?> Approve &amp; notify</button></div></form><?php else:?><p class="inline-note"><?=admin_icon('check')?> Approved · Player notification created.</p><?php endif?>
<details class="danger-zone"><summary>Delete submission</summary><p>This permanently removes the feedback text. Any undelivered approval notice is kept.</p><form method="post"><?php admin_csrf()?><input type="hidden" name="action" value="feedback_delete"><input type="hidden" name="feedback_id" value="<?=h((string)$item['id'])?>"><button class="danger">Delete feedback permanently</button></form></details></article><?php endforeach?>
<?php admin_pagination($dashboard,'feedback',['category'=>$dashboard['category'],'status'=>$dashboard['status']])?>
